class Provider implements CustomSource {
    api = "https://hentaiera.com"

    getSettings(): Settings {
        return {
            supportsAnime: false,
            supportsManga: true,
        }
    }

    private mapStatus(status?: string): string {
        if (!status) return "FINISHED"

        const s = String(status).toUpperCase()

        if (s.includes("ONGOING") || s.includes("PUBLISHING") || s.includes("RELEASING")) return "RELEASING"
        if (s.includes("COMPLETED") || s.includes("FINISHED")) return "FINISHED"
        if (s.includes("CANCELLED") || s.includes("DISCONTINUED")) return "CANCELLED"
        if (s.includes("HIATUS")) return "HIATUS"

        return "FINISHED"
    }

    private mapFormat(format?: string): string {
        if (!format) return "MANGA"

        const f = String(format).toUpperCase()

        if (f.includes("NOVEL")) return "NOVEL"
        if (f.includes("ONE") || f.includes("SHOT")) return "ONE_SHOT"

        return "MANGA"
    }

    async getMangaDetails(id: number): Promise<$app.AL_MangaDetailsById_Media | null> {
        const map = ($store.get("hentaiera") as any) || {}
        const realUrl = map[id]

        if (!realUrl) return null

        try {
            const item = await this.fetchGallery(realUrl)

            if (!item) return null

            return {
                id,
                siteUrl: item.url,
                status: this.mapStatus(item.status),
                type: "MANGA",
                format: this.mapFormat("MANGA"),
                title: {
                    userPreferred: item.title || "Unknown",
                    romaji: item.title || "Unknown",
                    english: item.title || "",
                    native: "",
                },
                coverImage: {
                    extraLarge: item.cover,
                    large: item.cover,
                    medium: item.cover,
                    color: "#ffffff",
                },
                description: item.description || "",
                isAdult: true,
                genres: item.genres || ["Adult", "HentaiEra"],
                synonyms: item.synonyms || [],
                startDate: item.startDate || {
                    year: new Date().getUTCFullYear(),
                    month: 1,
                    day: 1,
                },
                chapters: item.pageCount || 1,
                volumes: 0,
                nextAiringEpisode: null,
                relations: { edges: [] },
            } as any
        } catch (e) {
            console.error("HentaiEra getMangaDetails error:", e)
            return null
        }
    }

    async listManga(search: string, page: number, perPage: number): Promise<ListResponse<$app.AL_BaseManga>> {
        try {
            const query = String(search || "").trim()
            const currentPage = page && page > 0 ? page : 1
            const limit = Math.max(1, Math.min(perPage || 20, 30))

            let items: HentaiEraItem[] = []

            if (query.length > 0) {
                const directId = this.getGalleryId(query)

                if (directId) {
                    const direct = await this.fetchGallery(`${this.api}/gallery/${directId}/`)
                    items = direct ? [direct] : []
                } else if (query.indexOf("hentaiera.com") >= 0 && query.indexOf("/gallery/") >= 0) {
                    const direct = await this.fetchGallery(query)
                    items = direct ? [direct] : []
                } else {
                    items = await this.searchGalleries(query, currentPage, limit)
                }
            } else {
                items = await this.getLatestGalleries(currentPage, limit)
            }

            const idMap = ($store.get("hentaiera") as any) || {}
            const results: $app.AL_BaseManga[] = []

            for (const item of items) {
                if (!item || !item.url || !item.title) continue
                if (this.isBlockedText(item.title) || this.isBlockedText(item.description || "")) continue

                const id = this.hashString(item.url)
                idMap[id] = item.url

                results.push({
                    id,
                    siteUrl: item.url,
                    status: this.mapStatus(item.status),
                    type: "MANGA",
                    format: this.mapFormat("MANGA"),
                    title: {
                        userPreferred: item.title || "Untitled",
                        romaji: item.title || "Untitled",
                        english: item.title || "",
                        native: "",
                    },
                    coverImage: {
                        extraLarge: item.cover || "",
                        large: item.cover || "",
                        medium: item.cover || "",
                        color: "#ffffff",
                    },
                    bannerImage: item.cover || "",
                    description: item.description || "",
                    isAdult: true,
                    genres: item.genres || ["Adult", "HentaiEra"],
                    synonyms: item.synonyms || [],
                    startDate: item.startDate || {
                        year: new Date().getUTCFullYear(),
                        month: 1,
                        day: 1,
                    },
                    chapters: item.pageCount || 1,
                    volumes: 0,
                } as any)
            }

            $store.set("hentaiera", idMap)

            return {
                media: results,
                page: currentPage,
                totalPages: results.length >= limit ? currentPage + 1 : currentPage,
                total: results.length,
            }
        } catch (e) {
            console.error("HentaiEra listManga error:", e)
            return {
                media: [],
                page: 1,
                totalPages: 1,
                total: 0,
            }
        }
    }

