                if (!item) continue

                out.push({
                    id: numericId,
                    siteUrl: item.url,
                    status: this.mapStatus(item.status),
                    type: "MANGA",
                    format: this.mapFormat("MANGA"),
                    chapters: item.pageCount || 1,
