    private async searchGalleries(query: string, page: number, limit: number): Promise<HentaiEraItem[]> {
        const urls = [
            `${this.api}/?s=${encodeURIComponent(query)}`,
            `${this.api}/?q=${encodeURIComponent(query)}`,
            `${this.api}/?search=${encodeURIComponent(query)}`,
            `${this.api}/search/${encodeURIComponent(this.slugify(query))}/`,
            `${this.api}/search?query=${encodeURIComponent(query)}`,
            `${this.api}/search?q=${encodeURIComponent(query)}`,
        ]

        const seen: any = {}
        const all: HentaiEraItem[] = []

        for (const url of urls) {
            try {
                const html = await this.fetchText(url)

                if (!html || html.length < 300) continue

                const links = this.parseGalleryLinks(html)

                for (const link of links) {
                    if (!link.url || seen[link.url]) continue

                    const score = this.searchScore(query, link.title || this.titleFromUrl(link.url), link.url)

                    if (score < 35) continue

                    seen[link.url] = true

                    const detailed = await this.fetchGallery(link.url)

                    if (!detailed) continue

                    detailed.score = score

                    all.push(detailed)

                    if (all.length >= limit) break
                }

                if (all.length >= limit) break
            } catch (e) {
                console.error("HentaiEra search failed:", e)
            }
        }

        all.sort((a, b) => (b.score || 0) - (a.score || 0))

        return all.slice(0, limit)
    }

    private async getLatestGalleries(page: number, limit: number): Promise<HentaiEraItem[]> {
        const urls = [
            page > 1 ? `${this.api}/page/${page}/` : `${this.api}/`,
            `${this.api}/`,
        ]

        const seen: any = {}
        const out: HentaiEraItem[] = []

        for (const url of urls) {
            try {
                const html = await this.fetchText(url)

                if (!html || html.length < 300) continue

                const links = this.parseGalleryLinks(html)

                for (const link of links) {
                    if (!link.url || seen[link.url]) continue

                    seen[link.url] = true

                    const detailed = await this.fetchGallery(link.url)

                    if (!detailed) continue

                    out.push(detailed)

                    if (out.length >= limit) break
                }

                if (out.length > 0) break
            } catch (e) {
                console.error("HentaiEra latest failed:", e)
            }
        }

        return out
    }

    private async fetchGallery(inputUrl: string): Promise<HentaiEraItem | null> {
        const url = this.normalizeGalleryUrl(inputUrl)

        if (!url) return null

        const cacheKey = `hentaiera.gallery.${url}`
        const cached = $store.get(cacheKey) as HentaiEraItem | undefined

        if (cached && cached.url) {
            return cached
        }

        try {
            const html = await this.fetchText(url)

            if (!html || html.length < 300) return null

            const title = this.getGalleryTitle(html, url)

            if (!title || this.isBlockedText(title) || this.hasBlockedTags(html)) {
                return null
            }

            const cover =
                this.meta(html, "og:image") ||
                this.firstMatch(html, /<img[^>]+src=["']([^"']*\/cover\.(?:jpg|jpeg|png|webp))["']/i) ||
                this.firstMatch(html, /<img[^>]+src=["']([^"']*\/1t?\.(?:jpg|jpeg|png|webp))["']/i) ||
                ""

            const description =
                this.meta(html, "og:description") ||
                this.firstMatch(html, /<meta[^>]+name=["']description["'][^>]+content=["']([^"']+)["']/i) ||
                ""

            const genres = this.parseTags(html)
            const pageCount = this.parsePageCount(html)
            const language = this.getGalleryLanguage(html)
            const year = this.parseYear(html)

            const item: HentaiEraItem = {
                url,
                title,
                cover: this.normalizeUrl(cover),
                description: this.cleanText(description),
                genres: genres.length > 0 ? genres : ["Adult", "HentaiEra"],
                synonyms: this.parseSynonyms(html),
                status: "FINISHED",
                pageCount: pageCount || 1,
                language,
                startDate: {
                    year: year || new Date().getUTCFullYear(),
                    month: 1,
                    day: 1,
                },
            }

            $store.set(cacheKey, item)

            return item
        } catch (e) {
            console.error("HentaiEra fetchGallery error:", e)
            return null
        }
    }

    private parseGalleryLinks(html: string): HentaiEraLink[] {
        const out: HentaiEraLink[] = []
        const seen: any = {}

        const pattern = /<a[^>]+href=["']([^"']*\/gallery\/[0-9]+\/?[^"']*)["'][^>]*>([\s\S]*?)<\/a>/gi
        let match: RegExpExecArray | null

        while ((match = pattern.exec(html)) !== null) {
            const href = this.decode(match[1] || "")
            const inner = match[2] || ""
            const url = this.normalizeGalleryUrl(href)

            if (!url || seen[url]) continue

            const title =
                this.cleanSearchTitle(this.firstMatch(inner, /title=["']([^"']+)["']/i)) ||
                this.cleanSearchTitle(this.firstMatch(inner, /alt=["']([^"']+)["']/i)) ||
                this.cleanSearchTitle(inner) ||
                this.titleFromUrl(url)

            const image =
                this.firstMatch(inner, /data-src=["']([^"']+)["']/i) ||
                this.firstMatch(inner, /data-original=["']([^"']+)["']/i) ||
                this.firstMatch(inner, /data-lazy-src=["']([^"']+)["']/i) ||
                this.firstMatch(inner, /src=["']([^"']+)["']/i) ||
                ""

            if (this.isBlockedText(title)) continue

            seen[url] = true

            out.push({
                url,
                title,
                image: this.normalizeUrl(this.decode(image)),
            })
        }

        return out
    }

    private getGalleryTitle(html: string, url: string): string {
        let title =
            this.cleanText(this.firstMatch(html, /<h1[^>]*>([\s\S]*?)<\/h1>/i)) ||
            this.cleanText(this.meta(html, "og:title")) ||
            this.cleanText(this.firstMatch(html, /<title[^>]*>([\s\S]*?)<\/title>/i)) ||
            this.titleFromUrl(url)

        title = title
            .replace(/\s*-\s*HentaiEra\s*$/i, "")
            .replace(/\s*\|\s*HentaiEra\s*$/i, "")
            .replace(/\s*HentaiEra\s*$/i, "")
            .trim()

        return this.decode(title)
    }

    private parsePageCount(html: string): number {
        let max = 0

        const textCount =
            this.firstMatch(html, /Pages?\s*[:\-]?\s*([0-9]+)/i) ||
            this.firstMatch(html, /([0-9]+)\s*pages?/i)

        if (textCount) {
            max = Number(textCount) || 0
        }

        const patterns = [
            /\/([0-9]+)(?:t)?\.(?:jpg|jpeg|png|webp)/gi,
            /page[\s_-]?([0-9]+)/gi,
        ]

        for (const pattern of patterns) {
            let match: RegExpExecArray | null

            while ((match = pattern.exec(html)) !== null) {
                const n = Number(match[1] || 0)

                if (n > max) max = n
            }
        }

        return max || 1
    }

    private parseTags(html: string): string[] {
        const out: string[] = []
        const seen: any = {}
        const pattern = /\/(?:tag|artist|parody|character|group|category|language)\/[^"']+["'][^>]*>([\s\S]*?)<\/a>/gi
        let match: RegExpExecArray | null

        while ((match = pattern.exec(html)) !== null) {
            const text = this.cleanText(match[1] || "")

            if (!text || seen[text]) continue
            if (this.isBlockedText(text)) continue

            seen[text] = true
            out.push(text)
        }

        if (!seen["HentaiEra"]) out.push("HentaiEra")
        if (!seen["Adult"]) out.push("Adult")

        return out
    }

    private parseSynonyms(html: string): string[] {
        return this.parseTags(html).filter(x => x !== "HentaiEra" && x !== "Adult")
    }

    private getGalleryLanguage(html: string): string {
        const cleaned = this.cleanText(html).toLowerCase()

        if (cleaned.indexOf(" english ") >= 0) return "en"
        if (cleaned.indexOf(" japanese ") >= 0) return "ja"
        if (cleaned.indexOf(" spanish ") >= 0) return "es"
        if (cleaned.indexOf(" french ") >= 0) return "fr"
        if (cleaned.indexOf(" korean ") >= 0) return "ko"
        if (cleaned.indexOf(" german ") >= 0) return "de"
        if (cleaned.indexOf(" russian ") >= 0) return "ru"
        if (cleaned.indexOf(" portuguese ") >= 0) return "pt"
        if (cleaned.indexOf(" chinese ") >= 0) return "zh"

        return "en"
    }

    private parseYear(html: string): number {
        const year =
            this.firstMatch(html, /([12][0-9]{3})-[0-9]{2}-[0-9]{2}/i) ||
            this.firstMatch(html, /Release\s*Year\s*[:\-]?\s*([12][0-9]{3})/i) ||
            this.firstMatch(html, /Date\s*[:\-]?\s*([12][0-9]{3})/i)

        return Number(year || 0) || new Date().getUTCFullYear()
    }

    private normalizeGalleryUrl(input: string): string {
        const url = this.normalizeUrl(input)

        if (!url) return ""

        const id = this.getGalleryId(url)

        if (!id) return ""

        return `${this.api}/gallery/${id}/`
    }

    private normalizeUrl(input: string): string {
        let url = this.decode(String(input || "").trim())

        if (!url) return ""

        url = url
            .replace(/&amp;/g, "&")
            .replace(/\\u0026/g, "&")
            .replace(/\\\//g, "/")

        if (url.indexOf("//") === 0) return "https:" + url
        if (url.indexOf("/") === 0) return this.api + url
        if (url.indexOf("http") === 0) return url

        return `${this.api}/${url}`
    }

    private getGalleryId(input: string): string {
        const text = String(input || "").trim()

        const patterns = [
            /hentaiera\.com\/gallery\/([0-9]+)/i,
            /\/gallery\/([0-9]+)/i,
            /^([0-9]+)$/,
        ]

        for (const pattern of patterns) {
            const match = text.match(pattern)

            if (match && match[1]) return match[1]
        }

        return ""
    }

    private titleFromUrl(url: string): string {
        const id = this.getGalleryId(url)

        if (id) return `HentaiEra ${id}`

        return "HentaiEra Gallery"
    }

    private searchScore(query: string, title: string, url: string): number {
        const q = this.cleanComparable(query)
        const t = this.cleanComparable(title)
        const slug = this.cleanComparable(this.titleFromUrl(url))

        if (!q || !t) return 0

        let score = 0

        if (t === q) score += 100
        if (slug === q) score += 95
        if (t.indexOf(q) >= 0) score += 80
        if (q.indexOf(t) >= 0 && t.length >= 4) score += 55
        if (slug.indexOf(q) >= 0) score += 70

        const qWords = q.split(" ")
        const tWords = t.split(" ")
        const slugWords = slug.split(" ")

        let hits = 0
        let strongHits = 0

        for (const word of qWords) {
            if (!word || word.length < 2) continue

            if (this.arrayContainsWord(tWords, word) || this.arrayContainsWord(slugWords, word)) {
                hits++

                if (word.length >= 4) strongHits++
            }
        }

        if (qWords.length > 0) {
            score += Math.round((hits / qWords.length) * 45)
        }

        score += strongHits * 8

        if (qWords.length >= 2 && hits < Math.ceil(qWords.length * 0.55)) {
            score -= 40
        }

        if (String(title || "").length > 160) {
            score -= 20
        }

        return score
    }

    private arrayContainsWord(words: string[], target: string): boolean {
        for (const word of words) {
            if (word === target) return true
        }

        return false
    }

    private cleanComparable(input: string): string {
        return String(input || "")
            .toLowerCase()
            .replace(/\[[^\]]+\]/g, " ")
            .replace(/[^a-z0-9]+/g, " ")
            .replace(/\s+/g, " ")
            .trim()
    }

    private slugify(input: string): string {
        return String(input || "")
            .toLowerCase()
            .replace(/&/g, " and ")
            .replace(/['’]/g, "")
            .replace(/[^a-z0-9]+/g, "-")
            .replace(/^-+|-+$/g, "")
    }

    private cleanSearchTitle(input: string): string {
        let text = this.cleanText(input)

        text = text
            .replace(/\s+/g, " ")
            .replace(/\s*new\s*$/i, "")
            .replace(/\s*read now.*$/i, "")
            .replace(/\s*comments?.*$/i, "")
            .trim()

        if (text.length > 140) {
            text = text.slice(0, 140).trim()
        }

        return text
    }

    private hasBlockedTags(html: string): boolean {
        const text = this.cleanText(html)
        return this.isBlockedText(text)
    }

    private isBlockedText(input: string): boolean {
        const t = String(input || "").toLowerCase()

        return (
            t.indexOf("lolicon") >= 0 ||
            t.indexOf("shotacon") >= 0 ||
            t.indexOf("shota") >= 0 ||
            t.indexOf("loli") >= 0 ||
            t.indexOf("underage") >= 0 ||
            t.indexOf("minor") >= 0 ||
            t.indexOf("child") >= 0 ||
            t.indexOf("children") >= 0
        )
    }

    private async fetchText(url: string): Promise<string> {
        const cacheKey = `hentaiera.html.${url}`
        const cached = $store.get(cacheKey) as string | undefined

        if (cached) return cached

        const res = await fetch(url, {
            headers: {
                "Accept": "text/html,application/xhtml+xml,application/xml;q=0.9,*/*;q=0.8",
                "Accept-Language": "en-US,en;q=0.9",
                "User-Agent": "Mozilla/5.0",
                "Referer": this.api + "/",
            },
        })

        if (!res.ok) {
            throw new Error(`HTTP ${res.status} for ${url}`)
        }

        const text = await res.text()

        $store.set(cacheKey, text)

        return text
    }

    private meta(html: string, property: string): string {
        const escaped = this.escapeRegExp(property)

        const p1 = new RegExp(`<meta[^>]+property=["']${escaped}["'][^>]+content=["']([^"']+)["']`, "i")
        const p2 = new RegExp(`<meta[^>]+content=["']([^"']+)["'][^>]+property=["']${escaped}["']`, "i")
        const p3 = new RegExp(`<meta[^>]+name=["']${escaped}["'][^>]+content=["']([^"']+)["']`, "i")

        return this.decode(
            this.firstMatch(html, p1) ||
            this.firstMatch(html, p2) ||
            this.firstMatch(html, p3) ||
            "",
        )
    }

    private firstMatch(text: string, pattern: RegExp): string {
        const match = String(text || "").match(pattern)
        return match && match[1] ? match[1] : ""
    }

    private cleanText(input: string): string {
        return this.decode(
            String(input || "")
                .replace(/<script[\s\S]*?<\/script>/gi, " ")
                .replace(/<style[\s\S]*?<\/style>/gi, " ")
                .replace(/<[^>]+>/g, " ")
                .replace(/\s+/g, " ")
                .trim(),
        )
    }

    private decode(input: string): string {
        return String(input || "")
            .replace(/&amp;/g, "&")
            .replace(/&quot;/g, "\"")
            .replace(/&#39;/g, "'")
            .replace(/&apos;/g, "'")
            .replace(/&lt;/g, "<")
            .replace(/&gt;/g, ">")
            .replace(/&#x2F;/g, "/")
            .replace(/&#47;/g, "/")
            .replace(/&nbsp;/g, " ")
    }

    private escapeRegExp(input: string): string {
        return String(input || "").replace(/[.*+?^${}()|[\]\\]/g, "\\$&")
    }

    private hashString(input: string): number {
        if (!input) return 0

        let hash = 0

        for (let i = 0; i < input.length; i++) {
            hash = ((hash << 5) - hash) + input.charCodeAt(i)
            hash |= 0
        }

        return Math.abs(hash)
    }
}

type HentaiEraLink = {
    url: string
    title: string
    image: string
}

type HentaiEraItem = {
    url: string
    title: string
    cover: string
    description: string
    genres: string[]
    synonyms: string[]
    status: string
    pageCount: number
    language: string
    startDate: {
        year: number
        month?: number
        day?: number
    }
    score?: number
}
